import random
import string
from typing import List, Tuple

# This generator creates valid JSON text buffers targeting cJSON parsing and utilities.
# It aims to cover objects, arrays, strings (with escapes), numbers (ints/floats/exponent),
# booleans, null, nesting, mixed whitespace, and optional trailing NUL depending on fuzzer use.
# We always return a NUL-terminated buffer because cJSON stubs request strings via FUZZ_PARAM_STR
# which are used with c_str() or data(); providing a terminating NUL keeps inputs valid for both.
# Length-based APIs will ignore bytes after the first NUL if present, which is fine.

MAX_TOTAL_SIZE = 4096

WHITESPACE_SET = [" ", "\t", "\r", "\n"]

def rand_ws(rng: random.Random, min_len: int = 0, max_len: int = 6) -> str:
    n = rng.randint(min_len, max_len)
    return "".join(rng.choice(WHITESPACE_SET) for _ in range(n))

def rand_bool(rng: random.Random) -> str:
    return "true" if rng.random() < 0.5 else "false"

def rand_null() -> str:
    return "null"

def rand_int(rng: random.Random) -> str:
    # Cover small, large, negative, zero
    choices = [0, 1, -1, 42, -42, 2**31-1, -2**31, 2**53-1, -(2**53-1)]
    if rng.random() < 0.6:
        v = rng.choice(choices)
    else:
        # random magnitude
        sign = -1 if rng.random() < 0.3 else 1
        v = sign * rng.randint(0, 10**rng.randint(0, 12))
    return str(v)

def rand_fraction(rng: random.Random) -> str:
    # Generate a decimal fraction part
    digits = ''.join(rng.choice(string.digits) for _ in range(rng.randint(1, 8)))
    return f".{digits}"

def rand_exponent(rng: random.Random) -> str:
    e = rng.choice(['e', 'E'])
    sign = rng.choice(['', '+', '-'])
    digits = ''.join(rng.choice(string.digits) for _ in range(rng.randint(1, 3)))
    return f"{e}{sign}{digits}"

def rand_number(rng: random.Random) -> str:
    # Cover integer, float, exponent, combos, leading zeros avoidance per JSON spec
    if rng.random() < 0.4:
        base = rand_int(rng)
    else:
        # compose float
        sign = '-' if rng.random() < 0.3 else ''
        int_part = '0' if rng.random() < 0.3 else str(rng.randint(1, 999999))
        base = sign + int_part
        if rng.random() < 0.9:
            base += rand_fraction(rng)
        if rng.random() < 0.6:
            base += rand_exponent(rng)
    return base

SAFE_STRING_CHARS = (
    [c for c in string.ascii_letters + string.digits + " -_.:/@"]
)

ESCAPE_MAP = [
    ('\\\"', 'quote'),
    ('\\\\', 'backslash'),
    ('\\b', 'backspace'),
    ('\\f', 'formfeed'),
    ('\\n', 'newline'),
    ('\\r', 'carriage'),
    ('\\t', 'tab'),
]

def rand_unicode_escape(rng: random.Random) -> str:
    # Generate \uXXXX; occasionally surrogate pairs
    def hex4():
        return ''.join(rng.choice('0123456789abcdef') for _ in range(4))
    if rng.random() < 0.2:
        # surrogate pair in D800–DBFF, DC00–DFFF
        high = rng.randint(0xD800, 0xDBFF)
        low = rng.randint(0xDC00, 0xDFFF)
        return f"\\u{high:04x}\\u{low:04x}"
    return f"\\u{hex4()}"

def rand_string(rng: random.Random, min_len: int = 0, max_len: int = 32) -> str:
    n = rng.randint(min_len, max_len)
    parts: List[str] = []
    for _ in range(n):
        p = rng.random()
        if p < 0.1:
            parts.append(rng.choice([e[0] for e in ESCAPE_MAP]))
        elif p < 0.15:
            parts.append(rand_unicode_escape(rng))
        else:
            parts.append(rng.choice(SAFE_STRING_CHARS))
    s = ''.join(parts)
    return '"' + s + '"'

# Forward declarations via strings to allow recursion

def rand_value(rng: random.Random, depth: int) -> str:
    # Ensure depth control to avoid excessive size
    if depth <= 0:
        kind_weights: List[Tuple[str, float]] = [
            ('null', 0.1), ('bool', 0.15), ('number', 0.25), ('string', 0.3), ('array', 0.1), ('object', 0.1)
        ]
    else:
        kind_weights = [
            ('null', 0.05), ('bool', 0.1), ('number', 0.2), ('string', 0.25), ('array', 0.2), ('object', 0.2)
        ]
    kinds, weights = zip(*kind_weights)
    choice = rng.choices(kinds, weights=weights, k=1)[0]
    if choice == 'null':
        return rand_null()
    if choice == 'bool':
        return rand_bool(rng)
    if choice == 'number':
        return rand_number(rng)
    if choice == 'string':
        return rand_string(rng)
    if choice == 'array':
        return rand_array(rng, depth-1)
    return rand_object(rng, depth-1)

def rand_array(rng: random.Random, depth: int) -> str:
    # Generate an array with optional whitespace and trailing commas avoided (JSON disallows trailing)
    count = rng.randint(0, 8 if depth > 0 else 4)
    elems = []
    for i in range(count):
        v = rand_value(rng, depth)
        elems.append(f"{rand_ws(rng)}{v}{rand_ws(rng)}")
    inner = (",".join(elems))
    return f"[{rand_ws(rng)}{inner}{rand_ws(rng)}]"

KEY_START_CHARS = list(string.ascii_letters + string.digits + "_-$@")
KEY_CHARS = KEY_START_CHARS + list(" .:/#")

def rand_key(rng: random.Random) -> str:
    n = rng.randint(1, 16)
    s = rng.choice(KEY_START_CHARS) + ''.join(rng.choice(KEY_CHARS) for _ in range(n-1))
    # Allow escape coverage in keys occasionally
    if rng.random() < 0.15:
        s = s[:-1] + "\\" + '"'  # ensure an escaped quote in key
    return '"' + s + '"'

def rand_object(rng: random.Random, depth: int) -> str:
    # Generate an object with unique-ish keys and mixed value types
    count = rng.randint(0, 8 if depth > 0 else 4)
    items = []
    used = set()
    for _ in range(count):
        # Ensure keys differ most of the time
        for _attempt in range(5):
            k = rand_key(rng)
            if k not in used:
                used.add(k)
                break
        v = rand_value(rng, depth)
        items.append(f"{rand_ws(rng)}{k}{rand_ws(rng)}:{rand_ws(rng)}{v}{rand_ws(rng)}")
    inner = ",".join(items)
    return f"{{{rand_ws(rng)}{inner}{rand_ws(rng)}}}"

def assemble_top_level(rng: random.Random) -> str:
    # Build a top-level JSON that can be any value, sometimes with outer whitespace
    top = rand_value(rng, depth=rng.randint(1, 4))
    # Occasionally wrap multiple top-levels separated by whitespace only for length-based APIs? No, JSON must be single value.
    # But allow surrounding whitespace which parsers accept.
    return f"{rand_ws(rng)}{top}{rand_ws(rng)}"

def maybe_minify(s: str, rng: random.Random) -> str:
    # Return s unchanged or with minimal whitespace; since our generator already inserts limited whitespace,
    # this just occasionally strips to compact form.
    if rng.random() < 0.5:
        return s
    # crude minify: remove spaces/tabs/newlines not in strings using a simple state machine
    out = []
    in_str = False
    esc = False
    for ch in s:
        if in_str:
            out.append(ch)
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                in_str = False
        else:
            if ch == '"':
                in_str = True
                out.append(ch)
            elif ch in WHITESPACE_SET:
                # drop
                continue
            else:
                out.append(ch)
    return ''.join(out)

def clamp_size(b: bytes) -> bytes:
    if len(b) <= MAX_TOTAL_SIZE:
        return b
    # Clip safely at boundary before NUL and add NUL terminator
    trimmed = b[:MAX_TOTAL_SIZE-1]
    # Ensure no partial UTF-8 issues are critical for JSON validity; since JSON is ASCII-safe, trimming is fine.
    return trimmed + b"\0"

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose a top-level type distribution skewed toward objects/arrays since many APIs work on trees
    s = assemble_top_level(rng)

    # Occasionally generate specific interesting structures to trigger utils behavior
    mode = rng.random()
    if mode < 0.15:
        # JSON Patch example array
        ops = [
            '{"op":"add","path":"/a/b","value":1}',
            '{"op":"remove","path":"/a/b"}',
            '{"op":"replace","path":"/name","value":"X"}',
            '{"op":"move","from":"/a","path":"/b"}',
            '{"op":"copy","from":"/src","path":"/dst"}',
            '{"op":"test","path":"/t","value":true}'
        ]
        cnt = rng.randint(1, len(ops))
        chosen = ops[:]
        rng.shuffle(chosen)
        s = '[' + ','.join(chosen[:cnt]) + ']'
        s = rand_ws(rng) + s + rand_ws(rng)
    elif mode < 0.30:
        # JSON Pointer-friendly object
        obj = {
            "name": rand_string(rng, 3, 10)[1:-1],
            "items": [rng.randint(0, 5) for _ in range(rng.randint(0, 5))],
            "nested": {"A": 1, "b": 2, "c": [1, 2, 3]},
        }
        # Serialize simply
        def dumps(o):
            if isinstance(o, bool):
                return "true" if o else "false"
            if o is None:
                return "null"
            if isinstance(o, (int, float)):
                return str(o)
            if isinstance(o, str):
                # escape quotes and backslashes minimal
                esc = o.replace('\\', '\\\\').replace('"', '\\"')
                return '"' + esc + '"'
            if isinstance(o, list):
                return '[' + ','.join(dumps(v) for v in o) + ']'
            if isinstance(o, dict):
                return '{' + ','.join(dumps(k) + ':' + dumps(v) for k, v in o.items()) + '}'
            return 'null'
        s = dumps(obj)
        s = rand_ws(rng) + s + rand_ws(rng)

    # Maybe minify or keep formatted
    s = maybe_minify(s, rng)

    # Ensure NUL termination for c_str() users
    b = s.encode('utf-8') + b"\0"

    # Bound size
    b = clamp_size(b)
    return b
